INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('c1e4bf9e-d966-4ee8-b8c7-b697b05b8b2b', 'd63d9f2e-2bc8-4678-a6fb-dda4bd00829e', 1, 'PUBLISHED', 'Yến Mạch Qua Đêm Chuối Hạt Chia', 'Bữa sáng mát lành với yến mạch, chuối chín và hạt chia, chuẩn bị từ tối hôm trước.', 'Yến mạch được ngâm mềm cùng chuối nghiền và hạt chia, ăn kèm đậu phộng rang để bổ sung đạm thực vật và tạo độ giòn.', '7617e8d9-8134-44ec-8258-7890c6306872', NULL, '2026-10-03 07:22:03.366+00', 'yen mach qua dem chuoi hat chia', 'bua sang mat lanh voi yen mach chuoi chin va hat chia chuan bi tu toi hom truoc', 'yen mach duoc ngam mem cung chuoi nghien va hat chia an kem dau phong rang de bo sung dam thuc vat va tao do gion', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('527d98cb-9ef9-456f-b234-cf524a7ce165', '8a3e271e-8692-45ad-b0fe-d2102dc5352e', 1, 'PUBLISHED', 'Cháo Quinoa Bí Đỏ Hạt Bí', 'Cháo quinoa bí đỏ sánh mịn, điểm hạt bí rang cho bữa sáng ấm áp và giàu chất xơ.', 'Quinoa nấu cùng bí đỏ cho vị ngọt tự nhiên, thêm nước cốt dừa vừa đủ và hạt bí rang để tạo một bữa sáng cân bằng.', '3b6171ab-6ab2-486e-8f29-6fd0cedd4826', NULL, '2026-10-03 07:22:03.433+00', 'chao quinoa bi do hat bi', 'chao quinoa bi do sanh min diem hat bi rang cho bua sang am ap va giau chat xo', 'quinoa nau cung bi do cho vi ngot tu nhien them nuoc cot dua vua du va hat bi rang de tao mot bua sang can bang', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('e3251162-4fd0-478a-a06d-9d4d3b421423', '2310d4ca-8bc2-4e56-83dd-588e56e3a014', 1, 'PUBLISHED', 'Cơm Lứt Đậu Hũ Cải Bó Xôi Buổi Sáng', 'Tô cơm lứt đậu hũ và cải bó xôi cho buổi sáng cần nhiều năng lượng.', 'Cơm lứt mềm dùng cùng đậu hũ áp chảo, cải bó xôi và mè rang, phù hợp cho người thích bữa sáng mặn chắc bụng.', 'a424ce22-68c0-41a7-865c-bf0172067026', NULL, '2026-10-03 07:22:03.462+00', 'com lut dau hu cai bo xoi buoi sang', 'to com lut dau hu va cai bo xoi cho buoi sang can nhieu nang luong', 'com lut mem dung cung dau hu ap chao cai bo xoi va me rang phu hop cho nguoi thich bua sang man chac bung', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('3bc3ba2f-dfd8-434d-91c3-3e255ed05629', '39949fa6-22ef-4479-acce-6b850daa8ef2', 1, 'PUBLISHED', 'Cháo Hạt Sen Đậu Đỏ Yến Mạch', 'Cháo hạt sen, đậu đỏ và yến mạch mềm bùi cho bữa sáng no lâu.', 'Hạt sen và đậu đỏ được nấu mềm, kết hợp yến mạch tạo độ sánh tự nhiên và nguồn chất xơ dồi dào.', '3b6171ab-6ab2-486e-8f29-6fd0cedd4826', NULL, '2026-10-03 07:22:03.488+00', 'chao hat sen dau do yen mach', 'chao hat sen dau do va yen mach mem bui cho bua sang no lau', 'hat sen va dau do duoc nau mem ket hop yen mach tao do sanh tu nhien va nguon chat xo doi dao', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('4946a878-db1b-4827-841e-80a36a1dfc84', '9f95e90c-3200-4f1a-8ed4-8da7992002d6', 1, 'PUBLISHED', 'Cơm Lứt Tempeh Bông Cải Sốt Gừng', 'Hộp cơm trưa giàu đạm với tempeh, bông cải xanh và sốt gừng tamari.', 'Tempeh áp chảo thơm bùi dùng cùng cơm lứt và bông cải xanh, phù hợp chuẩn bị trước cho bữa trưa văn phòng.', '7617e8d9-8134-44ec-8258-7890c6306872', NULL, '2026-10-03 07:22:03.516+00', 'com lut tempeh bong cai sot gung', 'hop com trua giau dam voi tempeh bong cai xanh va sot gung tamari', 'tempeh ap chao thom bui dung cung com lut va bong cai xanh phu hop chuan bi truoc cho bua trua van phong', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('69fea7f6-2439-47f7-83b1-999a87507591', 'f08fd49b-a1cc-430b-a880-12bcb9e46a60', 1, 'PUBLISHED', 'Quinoa Đậu Gà Rau Củ Nướng', 'Tô quinoa đậu gà cùng bí đỏ, cà rốt và rau xanh cho bữa trưa nhiều màu sắc.', 'Đậu gà và rau củ được nướng thơm, trộn cùng quinoa và sốt chanh mè tạo bữa trưa giàu chất xơ.', '3b6171ab-6ab2-486e-8f29-6fd0cedd4826', NULL, '2026-10-03 07:22:03.544+00', 'quinoa dau ga rau cu nuong', 'to quinoa dau ga cung bi do ca rot va rau xanh cho bua trua nhieu mau sac', 'dau ga va rau cu duoc nuong thom tron cung quinoa va sot chanh me tao bua trua giau chat xo', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('fa4eb507-324b-47bd-9078-0caf38950932', '29330600-503c-43d1-9e7f-a667c8c2c07d', 1, 'PUBLISHED', 'Cà Ri Đậu Hũ Khoai Lang Dùng Với Cơm', 'Cà ri đậu hũ khoai lang béo thơm, dùng cùng cơm cho bữa trưa đủ năng lượng.', 'Đậu hũ, khoai lang và nấm nấu trong sốt cà ri nước cốt dừa, ăn kèm cơm ST25 nóng.', 'a424ce22-68c0-41a7-865c-bf0172067026', NULL, '2026-10-03 07:22:03.571+00', 'ca ri dau hu khoai lang dung voi com', 'ca ri dau hu khoai lang beo thom dung cung com cho bua trua du nang luong', 'dau hu khoai lang va nam nau trong sot ca ri nuoc cot dua an kem com st25 nong', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('f9ebbf03-e755-4066-b5ac-e23cbdee303b', '9da2a188-24af-4cce-8464-d2816a75a909', 1, 'PUBLISHED', 'Cơm Đậu Lăng Cà Tím Nướng', 'Cơm đậu lăng với cà tím nướng, cà chua và sốt thảo mộc cho bữa trưa no lâu.', 'Đậu lăng nấu mềm được trộn với cơm, dùng cùng cà tím nướng và cà chua tạo một phần ăn giàu đạm và chất xơ.', '7617e8d9-8134-44ec-8258-7890c6306872', NULL, '2026-10-03 07:22:03.599+00', 'com dau lang ca tim nuong', 'com dau lang voi ca tim nuong ca chua va sot thao moc cho bua trua no lau', 'dau lang nau mem duoc tron voi com dung cung ca tim nuong va ca chua tao mot phan an giau dam va chat xo', NULL, NULL, NULL);
