INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('4e707c93-7516-4f23-80e1-20c83667c7e1', 'dcc30be1-972e-4727-b51e-df81312da6ad', 1, 'PUBLISHED', 'Cà Tím Kho Đậu Hũ Dùng Với Cơm Lứt', 'Cà tím kho mềm thấm vị cùng đậu hũ và cơm lứt cho bữa tối gia đình.', 'Cà tím và đậu hũ được kho trong sốt gừng tamari đến khi sánh nhẹ, dùng cùng cơm lứt nóng.', 'a424ce22-68c0-41a7-865c-bf0172067026', NULL, '2026-10-03 07:22:03.658+00', 'ca tim kho dau hu dung voi com lut', 'ca tim kho mem tham vi cung dau hu va com lut cho bua toi gia dinh', 'ca tim va dau hu duoc kho trong sot gung tamari den khi sanh nhe dung cung com lut nong', NULL, NULL, NULL);
