INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('31a7eb2c-e51b-4656-af90-c594cd331513', 'bd727446-0ab1-4309-97c5-c821715dc025', 1, 'PUBLISHED', 'Cà Ri Chay Khoai Lang Nấm Nước Cốt Dừa', 'Vị béo ngậy của nước cốt dừa hòa quyện cùng khoai lang mật và nấm thơm lừng.', 'Món cà ri chay béo ngậy sánh mịn thơm nức hương sả và bột cà ri Ấn Độ. Từng miếng khoai lang mật bùi dẻo, đậu hũ thấm vị và nấm bào ngư dai giòn, chấm cùng bánh mì giòn rụm hoặc ăn với bún tươi đều xuất sắc.', '3b6171ab-6ab2-486e-8f29-6fd0cedd4826', NULL, '2026-09-28 03:15:29.47+00', 'ca ri chay khoai lang nam nuoc cot dua', 'vi beo ngay cua nuoc cot dua hoa quyen cung khoai lang mat va nam thom lung', 'mon ca ri chay beo ngay sanh min thom nuc huong sa va bot ca ri an do tung mieng khoai lang mat bui deo dau hu tham vi va nam bao ngu dai gion cham cung banh mi gion rum hoac an voi bun tuoi deu xuat sac', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('78234caf-7681-4431-b4ac-c29da1c06957', 'fc93fda6-b505-48f2-8eb0-5f2e85a4a891', 1, 'PUBLISHED', 'Phở Chay Hà Nội Nước Dùng Nấm & Hạt Sen', 'Hương vị phở Bắc ngọt thanh tự nhiên từ củ cải, hạt sen và nấm hương nướng.', 'Nồi nước dùng phở chay chuẩn vị không dùng hạt nêm công nghiệp mà tận dụng vị ngọt thanh từ củ cải trắng, mía lau, hạt sen và nấm hương nướng thơm cùng gừng già và hoa hồi. Kết hợp bánh phở tươi dẻo dai và sườn non chay áp chảo.', '3b6171ab-6ab2-486e-8f29-6fd0cedd4826', NULL, '2026-09-28 03:15:29.391+00', 'pho chay ha noi nuoc dung nam hat sen', 'huong vi pho bac ngot thanh tu nhien tu cu cai hat sen va nam huong nuong', 'noi nuoc dung pho chay chuan vi khong dung hat nem cong nghiep ma tan dung vi ngot thanh tu cu cai trang mia lau hat sen va nam huong nuong thom cung gung gia va hoa hoi ket hop banh pho tuoi deo dai va suon non chay ap chao', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('9c57485d-56e0-4063-804f-6e5c766bb90f', '6f294b1f-bbee-4aa9-82cd-74acca7fc8cf', 1, 'PUBLISHED', 'Bún Bò Huế Chay Sa Tế Sả Cay Đậm Đà', 'Tô bún đỏ rực màu hạt điều, dậy mùi sả ớt nồng nàn và riêu nấm thơm lừng.', 'Món bún cay nồng đậm chất miền Trung với nước dùng ninh từ bắp ngọt, củ cải, kết hợp sa tế sả ớt phi thơm cùng nấm đùi gà dai ngọt và đậu hũ chiên vàng.', 'a424ce22-68c0-41a7-865c-bf0172067026', NULL, '2026-09-28 03:15:29.446+00', 'bun bo hue chay sa te sa cay dam da', 'to bun do ruc mau hat dieu day mui sa ot nong nan va rieu nam thom lung', 'mon bun cay nong dam chat mien trung voi nuoc dung ninh tu bap ngot cu cai ket hop sa te sa ot phi thom cung nam dui ga dai ngot va dau hu chien vang', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('b940f036-53ba-4d14-b484-893d947b7a68', '5ef52ccb-2a36-497e-9141-de68a21aa4db', 1, 'PUBLISHED', 'Nấm Đông Cô Kho Tiêu Xanh Đậm Vị Đưa Cơm', 'Vị ngọt dai tự nhiên của nấm hương hòa cùng nước sốt kho kẹo cay nồng.', 'Món kho kinh điển trong bữa cơm chay gia đình. Nấm hương tươi chọn tai dày, chiên xém cạnh rồi kho liu riu trong nồi đất với nước tương tamari, tiêu xanh và dầu mè thơm nức mũi.', '3b6171ab-6ab2-486e-8f29-6fd0cedd4826', NULL, '2026-09-28 03:15:29.49+00', 'nam dong co kho tieu xanh dam vi dua com', 'vi ngot dai tu nhien cua nam huong hoa cung nuoc sot kho keo cay nong', 'mon kho kinh dien trong bua com chay gia dinh nam huong tuoi chon tai day chien xem canh roi kho liu riu trong noi dat voi nuoc tuong tamari tieu xanh va dau me thom nuc mui', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('bb6a79b0-a837-47b9-8541-227938a61697', '7e1ce9fd-1a46-4fe9-a9ad-1e8175909996', 1, 'PUBLISHED', 'Canh Chua Chay Nam Bộ Thơm Dứa & Nấm Bào Ngư', 'Bát canh chua hài hòa vị chua thanh từ me chín, ngọt từ dứa và nấm bào ngư.', 'Hương vị canh chua Nam Bộ thanh khiết giải nhiệt cho những ngày hè oi bức. Vị chua thanh tao từ me dốt, ngọt thanh từ dứa chín và bắp non, ăn kèm đậu hũ non mềm mịn tan trong miệng.', '3b6171ab-6ab2-486e-8f29-6fd0cedd4826', NULL, '2026-09-28 03:15:29.512+00', 'canh chua chay nam bo thom dua nam bao ngu', 'bat canh chua hai hoa vi chua thanh tu me chin ngot tu dua va nam bao ngu', 'huong vi canh chua nam bo thanh khiet giai nhiet cho nhung ngay he oi buc vi chua thanh tao tu me dot ngot thanh tu dua chin va bap non an kem dau hu non mem min tan trong mieng', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('3ce5ad43-7a21-4bfd-8868-3cbd9bb33956', '3af55602-6143-4bcd-8f8c-8cb52c97fd1b', 1, 'PUBLISHED', 'Gỏi Cuốn Chay Ngũ Sắc Sốt Bơ Đậu Phộng Tương Đen', 'Món cuốn thanh nhẹ tươi mát, chấm đẫm sốt bơ đậu phộng béo ngậy thơm ngon.', 'Từng cuộn gỏi trong veo nhìn thấu sắc cam của cà rốt, xanh non của xà lách, đỏ mọng của ớt chuông và vàng óng của đậu hũ áp chảo. Linh hồn món ăn nằm ở chén sốt bơ đậu phộng béo bùi chuẩn vị.', '3b6171ab-6ab2-486e-8f29-6fd0cedd4826', NULL, '2026-09-28 03:15:29.535+00', 'goi cuon chay ngu sac sot bo dau phong tuong den', 'mon cuon thanh nhe tuoi mat cham dam sot bo dau phong beo ngay thom ngon', 'tung cuon goi trong veo nhin thau sac cam cua ca rot xanh non cua xa lach do mong cua ot chuong va vang ong cua dau hu ap chao linh hon mon an nam o chen sot bo dau phong beo bui chuan vi', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('73f5d927-3d58-41d4-bd02-b4b045204740', 'c5171b08-779b-41dd-af15-47765c6f691a', 1, 'PUBLISHED', 'Cơm Chiên Trái Dứa Hạt Điều Ngũ Sắc', 'Hạt cơm gạo lứt tơi ráo, hạt điều giòn bùi và dứa chua ngọt bắt vị.', 'Món cơm chiên trình bày bắt mắt trong nửa trái dứa khoét ruột. Hạt cơm gạo lứt được rang săn hạt trên chảo nóng cùng hạt điều rang bùi béo, cà rốt giòn ngọt và nấm đùi gà dai ngon.', '3b6171ab-6ab2-486e-8f29-6fd0cedd4826', NULL, '2026-09-28 03:15:29.556+00', 'com chien trai dua hat dieu ngu sac', 'hat com gao lut toi rao hat dieu gion bui va dua chua ngot bat vi', 'mon com chien trinh bay bat mat trong nua trai dua khoet ruot hat com gao lut duoc rang san hat tren chao nong cung hat dieu rang bui beo ca rot gion ngot va nam dui ga dai ngon', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('3ef3b339-0734-4e7a-8db6-f4d68fb8ac36', 'b6421194-6c5a-4b64-b248-81a1a1d7720e', 1, 'PUBLISHED', 'Bánh Mì Chay Kẹp Pate Nấm Đậu Gà Thảo Mộc', 'Bánh mì giòn rụm phết pate nấm béo ngậy tự làm không chất bảo quản.', 'Pate chay thơm lừng từ đậu gà nghiền mịn kết hợp nấm hương xào thơm, bơ đậu phộng và men dinh dưỡng giàu B12. Kẹp trong ổ bánh mì nóng giòn cùng dưa leo, ngò rí và đồ chua giòn rụm.', '7617e8d9-8134-44ec-8258-7890c6306872', NULL, '2026-09-28 03:15:29.576+00', 'banh mi chay kep pate nam dau ga thao moc', 'banh mi gion rum phet pate nam beo ngay tu lam khong chat bao quan', 'pate chay thom lung tu dau ga nghien min ket hop nam huong xao thom bo dau phong va men dinh duong giau b12 kep trong o banh mi nong gion cung dua leo ngo ri va do chua gion rum', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('113fdb64-3008-473f-befd-e10374b74e64', '3cc5c9ee-5a25-45be-8f2f-7ebf177e6826', 1, 'PUBLISHED', 'Súp Bí Đỏ Kem Dừa Hạt Bí Rang Bổ Dưỡng', 'Món súp vàng ươm sánh mịn, ấm bụng cho bữa tối mùa thu đông.', 'Bí đỏ hồ lô nướng thơm ngọt đậm đà, nấu nhuyễn cùng nước cốt dừa béo bùi và rắc hạt bí ngô rang giòn tan. Giàu Beta-carotene và kẽm tốt cho làn da và hệ miễn dịch.', '7617e8d9-8134-44ec-8258-7890c6306872', NULL, '2026-09-28 03:15:29.598+00', 'sup bi do kem dua hat bi rang bo duong', 'mon sup vang uom sanh min am bung cho bua toi mua thu dong', 'bi do ho lo nuong thom ngot dam da nau nhuyen cung nuoc cot dua beo bui va rac hat bi ngo rang gion tan giau beta carotene va kem tot cho lan da va he mien dich', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('8e9c5750-9a40-4c54-af47-556f1da8b833', '1bde8689-c007-4ffb-af27-5c41170bcfbf', 1, 'PUBLISHED', 'Cháo Yến Mạch Nấm Hương Hạt Sen An Thần', 'Bát cháo dưỡng sinh thơm lừng, dễ tiêu hóa, hỗ trợ giấc ngủ sâu.', 'Bát cháo ấm nóng kết hợp yến mạch giàu chất xơ beta-glucan với hạt sen ninh bở và nấm hương thơm lừng. Rất thích hợp cho người lớn tuổi, người ốm mới dậy hoặc bữa sáng thanh nhẹ.', 'a424ce22-68c0-41a7-865c-bf0172067026', NULL, '2026-09-28 03:15:29.617+00', 'chao yen mach nam huong hat sen an than', 'bat chao duong sinh thom lung de tieu hoa ho tro giac ngu sau', 'bat chao am nong ket hop yen mach giau chat xo beta glucan voi hat sen ninh bo va nam huong thom lung rat thich hop cho nguoi lon tuoi nguoi om moi day hoac bua sang thanh nhe', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('a807c67c-05c5-4181-94a1-86f5e0003169', '491ab6c2-70e9-4738-875b-3efa3551d28c', 1, 'PUBLISHED', 'Salad Bơ Quả Đậu Gà Sốt Chanh Dây Dầu Oliu', 'Đĩa salad đầy màu sắc, cung cấp nguồn chất béo lành mạnh và đạm thực vật sạch.', 'Đậu gà bùi bở trộn cùng bơ sáp béo ngậy, cà chua bi mọng nước và cải bó xôi tươi giòn. Nước sốt chanh dây chua ngọt tươi mát kích thích vị giác tối đa.', '7617e8d9-8134-44ec-8258-7890c6306872', NULL, '2026-09-28 03:15:29.637+00', 'salad bo qua dau ga sot chanh day dau oliu', 'dia salad day mau sac cung cap nguon chat beo lanh manh va dam thuc vat sach', 'dau ga bui bo tron cung bo sap beo ngay ca chua bi mong nuoc va cai bo xoi tuoi gion nuoc sot chanh day chua ngot tuoi mat kich thich vi giac toi da', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('ab2b3050-7806-4894-b726-81690bfd2b2e', '81beeef2-4de5-4f39-9807-a1f4d2cbe7bd', 1, 'PUBLISHED', 'Sinh Tố Xanh Cải Bó Xôi Chuối Hạt Chia Detox', 'Ly sinh tố năng lượng xanh mướt, giàu sắt và kali cho buổi sáng tỉnh táo.', 'Công thức sinh tố xanh dễ uống nhất cho người mới bắt đầu. Vị ngọt tự nhiên của chuối tiêu chín làm dịu vị hăng của cải bó xôi, kết hợp hạt chia nở bung cung cấp Omega-3 quý giá.', '7617e8d9-8134-44ec-8258-7890c6306872', NULL, '2026-09-28 03:15:29.656+00', 'sinh to xanh cai bo xoi chuoi hat chia detox', 'ly sinh to nang luong xanh muot giau sat va kali cho buoi sang tinh tao', 'cong thuc sinh to xanh de uong nhat cho nguoi moi bat dau vi ngot tu nhien cua chuoi tieu chin lam diu vi hang cua cai bo xoi ket hop hat chia no bung cung cap omega 3 quy gia', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('8da3a655-c950-44cb-8fd7-3dab1b63f75c', 'efb8443d-e46a-419c-85c4-923397e6e38a', 1, 'PUBLISHED', 'Sữa Hạt Sen Đậu Đỏ Dưỡng Nhan Nóng Hổi', 'Ly sữa hạt thơm ngát béo ngậy, bồi bổ khí huyết và làm dịu tinh thần.', 'Sự kết hợp hoàn hảo giữa đậu đỏ hạt nhỏ giàu chất sắt và hạt sen tươi an thần. Thức uống ấm áp thơm thảo, không dùng sữa đặc hay đường tinh luyện mà giữ vị ngọt tự nhiên của hạt.', 'a424ce22-68c0-41a7-865c-bf0172067026', NULL, '2026-09-28 03:15:29.676+00', 'sua hat sen dau do duong nhan nong hoi', 'ly sua hat thom ngat beo ngay boi bo khi huyet va lam diu tinh than', 'su ket hop hoan hao giua dau do hat nho giau chat sat va hat sen tuoi an than thuc uong am ap thom thao khong dung sua dac hay duong tinh luyen ma giu vi ngot tu nhien cua hat', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('742753cd-6f05-407f-b479-aaa48b669aef', '0e7ed484-82d3-4337-9e4a-99f3f3278f4c', 1, 'PUBLISHED', 'Cẩm Nang Bổ Sung Vitamin B12 Toàn Diện Cho Người Ăn Thuần Chay', 'Hiểu đúng về nguồn gốc, nhu cầu sinh lý và giải pháp bổ sung Vitamin B12 an toàn, bền vững.', 'Vitamin B12 (Cobalamin) là vi chất thiết yếu đóng vai trò sống còn trong việc duy trì chức năng hệ thần kinh, tổng hợp DNA và sản sinh hồng cầu khỏe mạnh. Khác với thực vật có thể quang hợp tự dưỡng, Vitamin B12 được tổng hợp tự nhiên duy nhất bởi các vi sinh vật (vi khuẩn) sống trong đất và ruột động vật.
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('a039b774-a4e7-40ca-ad59-fab4b57dfa72', 'd5ba742b-ff01-4113-b95e-f5dfbd6f625f', 1, 'PUBLISHED', 'Tối Ưu Hóa Nguồn Đạm Thực Vật: Cách Phối Hợp Các Loại Đậu & Ngũ Cốc', 'Nguyên tắc vàng tạo chuỗi axit amin hoàn chỉnh và tối đa hóa hiệu suất xây dựng cơ bắp.', 'Một trong những băn khoăn lớn nhất của người mới chuyển sang chế độ ăn thực vật là: "Làm sao để nạp đủ protein mà không cần thịt cá?". Sự thật là vương quốc thực vật cung cấp nguồn đạm vô cùng phong phú và an toàn cho tim mạch.
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('6894d86f-a92c-48e0-9b86-9bc30b20c7d3', '923144ff-08a7-4cd3-982f-2a01246becff', 1, 'PUBLISHED', '7 Nguyên Tắc Vàng Meal Prep Chay: Tiết Kiệm Thời Gian & Luôn Đủ Chất Cả Tuần', 'Phương pháp chuẩn bị hộp cơm mang đi làm gọn gàng, rau củ luôn tươi giòn không chảy nước.', 'Meal Prep (chuẩn bị trước bữa ăn) là chìa khóa vàng giúp bạn duy trì lối sống lành mạnh ngay cả trong những tuần lễ bận rộn nhất.
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('046ef7d8-0b32-45a4-8732-e376f4aee2ad', '1568d8c1-c461-4fae-abda-882dc25e3692', 1, 'PUBLISHED', 'Phân Biệt Các Trường Phái Ăn Chay & Lộ Trình Chuyển Đổi Không Mệt Mỏi', 'Từ Chay Kỳ, Lacto-Ovo đến Thuần Chay Vegan: Đâu là lựa chọn phù hợp nhất với thể trạng của bạn?', 'Ẩm thực chay không có một khuôn mẫu cứng nhắc duy nhất, mà là một phổ thực hành phong phú tôn trọng sự lựa chọn và thể trạng của mỗi cá nhân.
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('60be9081-a8a1-4dfc-ba2f-acb90fe943b4', '42679fc1-fdb1-4de8-82fb-f8acf9f370ba', 1, 'PUBLISHED', 'Video Hướng Dẫn: Bí Quyết Nấu Nước Dùng Phở Chay Ngọt Thanh Tự Nhiên Không Mì Chính', 'Từng bước nướng thơm gia vị, ninh củ quả và hầm nấm sen tạo vị ngọt thanh sâu lắng.', 'Trong video dài 12 phút này, Bếp Trưởng Minh Tâm sẽ chia sẻ kỹ thuật hãm lửa và chọn nguyên liệu củ quả theo tỷ lệ vàng để nước phở trong veo, ngọt thanh tự nhiên mà không cần bất kỳ hạt nêm công nghiệp nào.', '3b6171ab-6ab2-486e-8f29-6fd0cedd4826', NULL, '2026-09-28 03:15:29.768+00', 'video huong dan bi quyet nau nuoc dung pho chay ngot thanh tu nhien khong mi chinh', 'tung buoc nuong thom gia vi ninh cu qua va ham nam sen tao vi ngot thanh sau lang', 'trong video dai 12 phut nay bep truong minh tam se chia se ky thuat ham lua va chon nguyen lieu cu qua theo ty le vang de nuoc pho trong veo ngot thanh tu nhien ma khong can bat ky hat nem cong nghiep nao', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('6776a3ec-660a-4ec5-99de-d9c6048e7145', 'a10382d9-a87b-4c43-a8ca-8f57da459255', 1, 'PUBLISHED', 'Video Hướng Dẫn: 15 Phút Nấu Bữa Tối Chay Nhanh Gọn Cho Người Bận Rộn', 'Cách sắp xếp gian bếp và chuẩn bị 2 món xào - canh nóng hổi chỉ trong 15 phút.', 'Video hướng dẫn thao tác song song giữa bếp xào đậu hũ bông cải và nồi canh chua thanh mát. Phù hợp cho các bạn trẻ văn phòng sau giờ làm tan ca.', '3b6171ab-6ab2-486e-8f29-6fd0cedd4826', NULL, '2026-09-28 03:15:29.786+00', 'video huong dan 15 phut nau bua toi chay nhanh gon cho nguoi ban ron', 'cach sap xep gian bep va chuan bi 2 mon xao canh nong hoi chi trong 15 phut', 'video huong dan thao tac song song giua bep xao dau hu bong cai va noi canh chua thanh mat phu hop cho cac ban tre van phong sau gio lam tan ca', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('46c9c2ba-7c2e-4720-90de-c3d6c505ef29', '969d1418-75b4-4d29-8947-eac4876c8913', 1, 'PUBLISHED', 'Video Hướng Dẫn: Nấu Sữa Hạt Sen Đậu Đỏ Thơm Béo Mịn Bằng Máy Xay Sinh Tố', 'Cách làm sữa hạt sánh dẻo tại nhà không tách nước, không cần lọc bỏ bã.', 'Video chia sẻ mẹo nấu chín hạt sen và đậu đỏ trước khi xay cùng yến mạch để ly sữa hạt mịn màng, giàu chất xơ hòa tan và giữ trọn hương thơm tự nhiên.', 'a424ce22-68c0-41a7-865c-bf0172067026', NULL, '2026-09-28 03:15:29.802+00', 'video huong dan nau sua hat sen dau do thom beo min bang may xay sinh to', 'cach lam sua hat sanh deo tai nha khong tach nuoc khong can loc bo ba', 'video chia se meo nau chin hat sen va dau do truoc khi xay cung yen mach de ly sua hat min mang giau chat xo hoa tan va giu tron huong thom tu nhien', NULL, NULL, NULL);
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('a2100000-0000-4000-8000-000000000005', 'a2000000-0000-4000-8000-000000000004', 1, 'PUBLISHED', 'Nấm om gạo lứt nhiều bước', 'Công thức mức khó để frontend hiển thị đủ bộ lọc độ khó.', 'Ngâm gạo, sơ chế nấm, nấu nền rau củ rồi om chậm đến khi đạt độ sánh.', '935530b9-5b38-48f4-83ba-50d9b5cbf0bf', NULL, '2026-09-19 02:56:09.48+00', 'nam om gao lut nhieu buoc', 'cong thuc muc kho de frontend hien thi du bo loc do kho', 'ngam gao so che nam nau nen rau cu roi om cham den khi dat do sanh', NULL, NULL, '2026-09-19 02:56:09.48+00');
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('a2100000-0000-4000-8000-000000000002', 'a2000000-0000-4000-8000-000000000002', 1, 'REJECTED', 'Bài viết cần sửa nguồn tham khảo', 'Fixture để Contributor xem lý do từ chối và tạo bản sửa.', 'Nội dung demo chưa trình bày đủ căn cứ cho một nhận định dinh dưỡng.', 'ef5f5340-4a3a-4a2f-b1eb-b02de9d5de35', 'Vui lòng bổ sung nguồn và diễn đạt lại nhận định dinh dưỡng.', '2026-09-19 02:56:09.434+00', 'bai viet can sua nguon tham khao', 'fixture de contributor xem ly do tu choi va tao ban sua', 'noi dung demo chua trinh bay du can cu cho mot nhan dinh dinh duong', 'f509811b-0852-45cb-8b36-4479f4080753', '2026-09-15 04:00:00+00', '2026-09-19 02:56:09.434+00');
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('a2100000-0000-4000-8000-000000000003', 'a2000000-0000-4000-8000-000000000003', 1, 'PUBLISHED', 'Cơm gạo lứt đậu hũ nhiều rau', 'Công thức đã xuất bản, dùng để kiểm tra bản sửa vẫn đang chờ duyệt.', 'Nấu gạo lứt, áp chảo đậu hũ và dùng cùng bông cải đã hấp chín.', 'ef5f5340-4a3a-4a2f-b1eb-b02de9d5de35', NULL, '2026-09-19 02:56:09.445+00', 'com gao lut dau hu nhieu rau', 'cong thuc da xuat ban dung de kiem tra ban sua van dang cho duyet', 'nau gao lut ap chao dau hu va dung cung bong cai da hap chin', NULL, NULL, '2026-09-19 02:56:09.445+00');
INSERT INTO public.post_revisions (id, post_id, version, status, title, excerpt, body, created_by_id, review_note, created_at, normalized_title, normalized_excerpt, normalized_body, reviewed_by_id, reviewed_at, submitted_at) VALUES ('a2100000-0000-4000-8000-000000000004', 'a2000000-0000-4000-8000-000000000003', 2, 'PENDING_REVIEW', 'Cơm gạo lứt đậu hũ nhiều rau - bản cập nhật', 'Bản cập nhật tăng lượng rau đang chờ Admin duyệt.', 'Nấu gạo lứt, áp chảo đậu hũ và tăng khẩu phần bông cải hấp chín.', 'ef5f5340-4a3a-4a2f-b1eb-b02de9d5de35', NULL, '2026-09-19 02:56:09.462+00', 'com gao lut dau hu nhieu rau ban cap nhat', 'ban cap nhat tang luong rau dang cho admin duyet', 'nau gao lut ap chao dau hu va tang khau phan bong cai hap chin', NULL, NULL, '2026-09-19 02:56:09.462+00');
