INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('75e3b757-7625-4230-8a89-c497e68b9b05', '78234caf-7681-4431-b4ac-c29da1c06957', 0, 'Nướng gừng già trên lửa nhỏ cho thơm vỏ. Củ cải gọt vỏ cắt khúc 3cm.', 'e73a4e1f-4d0d-4376-8ebd-9d5e878ae0a8', 5, NULL, '[3, 6]', '2026-09-28 03:15:29.391+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('1ae8c04f-d8a2-499f-acd2-f21cb8631c3a', '78234caf-7681-4431-b4ac-c29da1c06957', 1, 'Ninh củ cải, hạt sen, gừng nướng và chân nấm hương trong 1.2 lít nước để lấy nước dùng ngọt thanh.', '4652f00a-a546-47da-a185-b1ecfa70f72d', 30, NULL, '[1, 2, 3, 6]', '2026-09-28 03:15:29.391+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('9de14666-64db-4502-ad75-abb85a90252f', '78234caf-7681-4431-b4ac-c29da1c06957', 2, 'Sườn non chay xé sợi, ướp chút tương tamari rồi áp chảo vàng giòn cùng nấm hương thái lát.', '83199ef1-0bbf-4305-9cf9-9986e7924e55', 7, NULL, '[1, 4]', '2026-09-28 03:15:29.391+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('ca2f5480-1647-435d-bdc4-c4ae71a97d6d', '78234caf-7681-4431-b4ac-c29da1c06957', 3, 'Trần bánh phở qua nước sôi, xếp vào tô cùng nấm, sườn non chay và hành boaro, chan nước dùng sôi sùng sục.', NULL, 3, NULL, '[0, 5]', '2026-09-28 03:15:29.391+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('a5f701bd-a075-4392-bf0b-f87a12b201f6', '9c57485d-56e0-4063-804f-6e5c766bb90f', 0, 'Nấu nước dùng ngọt từ bắp ngọt và sả đập dập sôi liu riu trong 20 phút.', '4652f00a-a546-47da-a185-b1ecfa70f72d', 20, NULL, '[3, 4]', '2026-09-28 03:15:29.446+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('3d7e5a18-a2bb-4acf-84c7-01c18dccce2c', '9c57485d-56e0-4063-804f-6e5c766bb90f', 1, 'Phi thơm hành boaro và sả băm với ớt sa tế, cho nấm đùi gà và đậu hũ vào xào ngấm gia vị.', '83199ef1-0bbf-4305-9cf9-9986e7924e55', 8, NULL, '[1, 2, 5]', '2026-09-28 03:15:29.446+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('bbe50cbc-b63f-447d-802a-cdb7c34df59b', '9c57485d-56e0-4063-804f-6e5c766bb90f', 2, 'Trút phần nhân xào vào nồi nước dùng, nêm chút hạt nêm nấm và muối hồng vừa ăn.', NULL, 5, NULL, '[1, 2]', '2026-09-28 03:15:29.446+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('339467b9-1329-49aa-8238-8526c49f11e5', '9c57485d-56e0-4063-804f-6e5c766bb90f', 3, 'Cho bún vào tô, xếp đậu hũ, nấm đùi gà, chan nước dùng cay nồng ăn kèm rau bắp chuối và rau thơm.', NULL, 2, NULL, '[0]', '2026-09-28 03:15:29.446+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('57b9447a-4d53-4a09-8002-02442051cb3b', '31a7eb2c-e51b-4656-af90-c594cd331513', 0, 'Chiên sơ khoai lang và cà rốt trên chảo để khoai không bị nát khi hầm.', 'ee7fd781-7e0f-45a6-9c27-2f6e3eed16b9', 10, NULL, '[0, 4]', '2026-09-28 03:15:29.47+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('e0e06534-2958-4e58-9da9-33c4b870ac32', '31a7eb2c-e51b-4656-af90-c594cd331513', 1, 'Phi sả đập dập cùng bột cà ri, xào săn nấm bào ngư và đậu hũ cho thấm màu vàng đẹp mắt.', '83199ef1-0bbf-4305-9cf9-9986e7924e55', 5, NULL, '[1, 2, 5]', '2026-09-28 03:15:29.47+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('6c16eb96-053e-4895-94c1-09c60eea5a91', '31a7eb2c-e51b-4656-af90-c594cd331513', 2, 'Thêm 500ml nước lọc và sả cây vào hầm khoai, cà rốt mềm trong 12 phút.', '4652f00a-a546-47da-a185-b1ecfa70f72d', 12, NULL, '[0, 4, 5]', '2026-09-28 03:15:29.47+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('3d22ecea-5369-4512-8984-a4ccef04d559', '31a7eb2c-e51b-4656-af90-c594cd331513', 3, 'Hạ lửa nhỏ, rưới nước cốt dừa vào khuấy đều, đun sôi lăn tăn 3 phút rồi tắt bếp.', NULL, 3, NULL, '[3]', '2026-09-28 03:15:29.47+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('fa375945-ebb9-4f15-8437-d83405174346', 'b940f036-53ba-4d14-b484-893d947b7a68', 0, 'Nấm hương khía chữ thập trên mũ nấm, áp chảo vàng nhẹ 2 mặt.', '83199ef1-0bbf-4305-9cf9-9986e7924e55', 5, NULL, '[0]', '2026-09-28 03:15:29.49+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('6374a8cc-ab91-4794-a9ee-5cff5db7434e', 'b940f036-53ba-4d14-b484-893d947b7a68', 1, 'Phi thơm hành boaro trong tộ đất, cho nấm vào đảo đều cùng nước tương tamari và 50ml nước dừa tươi.', NULL, 3, NULL, '[0, 1, 3]', '2026-09-28 03:15:29.49+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('5ee4f031-4fa0-4687-9674-91cb45b4b1b0', 'b940f036-53ba-4d14-b484-893d947b7a68', 2, 'Kho lửa nhỏ liu riu cho nước sốt sánh kẹo lại, rắc tiêu xay và rưới dầu mè trước khi tắt bếp.', NULL, 7, NULL, '[0, 2]', '2026-09-28 03:15:29.49+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('081db8b6-d079-481f-a6de-a56642abef2d', 'bb6a79b0-a837-47b9-8541-227938a61697', 0, 'Xào thơm cà chua và dứa trong nồi với chút dầu ăn để tạo màu nước canh đẹp.', '83199ef1-0bbf-4305-9cf9-9986e7924e55', 4, NULL, '[2, 3]', '2026-09-28 03:15:29.512+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('2088d1b5-2754-45ba-b72e-4b155388bb0e', 'bb6a79b0-a837-47b9-8541-227938a61697', 1, 'Cho 800ml nước vào đun sôi cùng bắp ngọt, nấm bào ngư và nước cốt me chua.', '4652f00a-a546-47da-a185-b1ecfa70f72d', 8, NULL, '[1, 4]', '2026-09-28 03:15:29.512+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('a4bf7f39-1783-40fc-aa17-fe1585690ba3', 'bb6a79b0-a837-47b9-8541-227938a61697', 2, 'Thả đậu hũ non vào nấu nhẹ tay 3 phút, nêm muối và hạt nêm nấm vừa vị chua ngọt thanh tao.', NULL, 3, NULL, '[0]', '2026-09-28 03:15:29.512+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('1cd31837-bb35-4bc5-9cb8-6de1577dae9e', 'bb6a79b0-a837-47b9-8541-227938a61697', 3, 'Múc ra tô, rắc ngò gai, ngò rí thái nhỏ và vài lát ớt sừng ăn nóng.', NULL, 1, NULL, '[5]', '2026-09-28 03:15:29.512+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('f6b560e3-c907-4655-9862-3399f5e170d0', '3ce5ad43-7a21-4bfd-8868-3cbd9bb33956', 0, 'Áp chảo đậu hũ thái que cho vàng giòn các mặt với chút muối tiêu.', '83199ef1-0bbf-4305-9cf9-9986e7924e55', 5, NULL, '[0]', '2026-09-28 03:15:29.535+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('47c1d705-9251-473d-a9ca-7f4693211b95', '3ce5ad43-7a21-4bfd-8868-3cbd9bb33956', 1, 'Khuấy đều bơ đậu phộng với nước tương tamari, nước ấm và chút chanh tạo sốt chấm sánh mịn.', NULL, 3, NULL, '[2]', '2026-09-28 03:15:29.535+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('7e00b515-71a5-43bd-a780-459b527c4ef7', '3ce5ad43-7a21-4bfd-8868-3cbd9bb33956', 2, 'Thấm ướt bánh tráng, xếp bún, đậu hũ, cà rốt và rau thơm cuộn tròn chặt tay.', NULL, 7, NULL, '[0, 1, 3, 4]', '2026-09-28 03:15:29.535+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('5f8eea28-ff3f-4d22-bc82-90ffac66ea3f', '73f5d927-3d58-41d4-bd02-b4b045204740', 0, 'Xào nhanh cà rốt và nấm đùi gà trên chảo nóng với chút dầu mè cho chín tới.', '83199ef1-0bbf-4305-9cf9-9986e7924e55', 4, NULL, '[3, 4, 5]', '2026-09-28 03:15:29.556+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('104d2b0f-4c29-482f-ab14-e2a40db1dae9', '73f5d927-3d58-41d4-bd02-b4b045204740', 1, 'Cho cơm gạo lứt vào đảo đều tay trên lửa lớn để hạt cơm tơi săn và dậy mùi thơm.', '83199ef1-0bbf-4305-9cf9-9986e7924e55', 6, NULL, '[0]', '2026-09-28 03:15:29.556+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('945e8fe9-e2e8-4842-8ada-290768ae95ca', '73f5d927-3d58-41d4-bd02-b4b045204740', 2, 'Trút dứa và hạt điều vào đảo nhanh 2 phút, nêm hạt nêm nấm rồi xúc vào vỏ trái dứa.', NULL, 2, NULL, '[1, 2]', '2026-09-28 03:15:29.556+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('9496b638-82a7-46e7-9c47-bc5c1be32e09', '3ef3b339-0734-4e7a-8db6-f4d68fb8ac36', 0, 'Xay nhuyễn đậu gà chín cùng nấm hương xào, men dinh dưỡng và chút dầu mè tạo pate mịn thơm.', NULL, 5, NULL, '[0, 1, 2]', '2026-09-28 03:15:29.576+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('e73ed62b-99d9-4403-a2cf-24aad161b809', '3ef3b339-0734-4e7a-8db6-f4d68fb8ac36', 1, 'Nướng nóng giòn ổ bánh mì, rạch bụng phết đẫm một lớp pate nấm đậu gà.', 'e73a4e1f-4d0d-4376-8ebd-9d5e878ae0a8', 3, NULL, '[]', '2026-09-28 03:15:29.576+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('ccdec2db-e3e2-436f-bc82-31bad58a7ae6', '3ef3b339-0734-4e7a-8db6-f4d68fb8ac36', 2, 'Xếp chả chay, dưa leo, cà rốt đồ chua và ngò rí vào ổ bánh, rưới chút xì dầu và tiêu xay.', NULL, 2, NULL, '[3, 4, 5]', '2026-09-28 03:15:29.576+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('8d081653-c15c-49b7-9453-9933b3e41dff', '113fdb64-3008-473f-befd-e10374b74e64', 0, 'Hấp hoặc luộc chín mềm bí đỏ cùng một lát gừng đập dập.', '1e4fcdeb-9875-494d-98f7-8ed3ba6c2bd5', 12, NULL, '[0, 3]', '2026-09-28 03:15:29.598+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('484fd542-cce7-4c0b-9e9e-a52e4ebeec5a', '113fdb64-3008-473f-befd-e10374b74e64', 1, 'Cho bí đỏ chín cùng nước luộc và nước cốt dừa vào máy xay sinh tố xay nhuyễn mịn.', NULL, 3, NULL, '[0, 1]', '2026-09-28 03:15:29.598+00');
INSERT INTO public.recipe_steps (id, revision_id, "position", instruction, cooking_method_id, duration_minutes, temperature_celsius, affected_ingredient_positions, created_at) VALUES ('10df3e3f-d9d0-4e6a-ae92-5079d5b7ad12', '113fdb64-3008-473f-befd-e10374b74e64', 2, 'Đổ lại vào nồi đun sôi nhẹ 2 phút, nêm chút muối hồng và tiêu trắng.', NULL, 2, NULL, '[]', '2026-09-28 03:15:29.598+00');
